SELECT approval_id
FROM card_payment_approvals
WHERE user_id = #{userId}
  AND approval_status = 'approved'
  AND approved_at >= #{fromUtc}
  AND approved_at < #{toUtc}
ORDER BY approved_at, approval_id

SELECT COALESCE(SUM(CASE WHEN usage_date = #{usageDate} THEN usage_count ELSE 0 END), 0)
           AS daily_count,
       COALESCE(SUM(usage_count), 0) AS monthly_count
FROM user_benefit_usages
WHERE user_card_id = #{userCardId}
  AND offer_id = #{offerId}
  AND usage_status = 'confirmed'
  AND usage_date >= #{usageMonthStart}
  AND usage_date < #{nextMonthStart}

SELECT current_spend_amount
FROM user_card_performance_snapshots
WHERE user_card_id = #{userCardId} AND performance_month = #{performanceMonth}

SELECT current_spend_amount
FROM user_card_performance_snapshots
WHERE user_card_id = #{userCardId} AND performance_month = #{performanceMonth}

SELECT COALESCE(SUM(reward_amount_krw), 0)
FROM user_benefit_usages
WHERE user_card_id = #{userCardId}
  AND offer_id = #{offerId}
  AND usage_status = 'confirmed'
  AND usage_date >= #{usageMonthStart}
  AND usage_date < #{nextMonthStart}
FOR UPDATE
